import {makeLocalPlan,parsePrompt,mapURL,money,addDays,today,localChat} from './local-planner.js';

const $=selector=>document.querySelector(selector), esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=url=>{try{if(String(url).startsWith('/assets/'))return url;const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
const icons={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15m6-12v15"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',wallet:'<path d="M20 7V4H5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h15V9H5a2 2 0 0 1 0-4"/><path d="M20 13h-5v4h5"/>',arrow:'<path d="M7 17 17 7M7 7h10v10"/>',right:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',plane:'<path d="m22 2-7 20-4-9-9-4zM22 2 11 13"/>',bed:'<path d="M3 18h18M3 21V7m18 14V11H3m3 0V6h12v5M3 15h18"/>',coffee:'<path d="M18 8h1a3 3 0 1 1 0 6h-1M3 8h15v8a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4zM6 2v3m5-3v3m5-3v3"/>',save:'<path d="M5 3h14v19l-7-5-7 5z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',check:'<path d="m4 12 5 5L20 6"/>',chat:'<path d="M21 15a3 3 0 0 1-3 3H8l-5 4V6a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3z"/><path d="M7 8h10M7 12h7"/>',settings:'<path d="M4 6h16M4 18h16M4 12h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',star:'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',print:'<path d="M6 9V3h12v6M6 18H3V9h18v9h-3M6 14h12v8H6z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',bag:'<rect x="4" y="6" width="16" height="15" rx="2"/><path d="M9 6V3h6v3M8 6v15m8-15v15"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.compass}</svg>`}
const DEFAULT_PROMPT="Plan a 6-day Bali trip for 2 people from Kolkata in December. Budget ₹1.4 lakh. We like beaches, nightlife, adventure and good hotels. Don't make the schedule exhausting.";
const COLORS=['#6b93ff','#e5f45d','#8bd3bb','#a9a2f7','#72c2e7','#d7a17c'];
const state={view:'studio',catalog:[],config:null,preview:true,user:null,authMode:'login',authBusy:false,pendingSave:false,prompt:DEFAULT_PROMPT,overrides:{},plan:null,tab:'overview',day:1,busy:false,error:'',saved:[],messages:[],chatBusy:false,deleteId:null,abort:null};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600)}
function loadSaved(){try{const data=JSON.parse(localStorage.getItem('voyageos.trips.v1')||'[]');state.saved=Array.isArray(data)?data.filter(p=>p&&p.id&&p.brief&&Array.isArray(p.days)&&p.budget&&p.destination).slice(0,30):[]}catch{state.saved=[]}}
function persist(){try{localStorage.setItem('voyageos.trips.v1',JSON.stringify(state.saved));return true}catch{toast('Browser storage is unavailable or full. Download your trip instead.');return false}}
function dateLabel(iso,opts={day:'numeric',month:'short',year:'numeric'}){return iso?new Date(iso+'T12:00:00').toLocaleDateString('en-IN',opts):'Flexible dates'}
function tripDates(b){if(!b.start_date)return 'Flexible dates';return `${dateLabel(b.start_date,{day:'numeric',month:'short'})} – ${dateLabel(addDays(b.start_date,b.days-1))}`}
function link(url,text,classes=''){return `<a class="${classes}" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${text}</a>`}
function picture(src,alt,classes='',extra=''){return `<img class="${classes}" src="${esc(safeURL(src))}" alt="${esc(alt)}" loading="lazy" ${extra}>`}
function nav(){const rows=[['studio','spark','Trip studio'],['saved','save','My trips'],['explore','globe','Explore destinations']];$('#nav').innerHTML=rows.map(([id,i,label])=>`<button class="nav-button ${state.view===id?'active':''}" data-nav="${id}" ${state.view===id?'aria-current="page"':''} title="${label}">${icon(i)}<span>${label}</span>${id==='saved'&&state.saved.length?`<span class="count">${state.saved.length}</span>`:''}</button>`).join('');$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${state.view==='saved'?'My trips':state.view==='explore'?'Explore':state.plan?'Your itinerary':'Trip studio'}`;const name=state.user?.name||'Your travel space',initials=state.user?state.user.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase():'YOU';$('#account-label').textContent=state.user?state.user.name.split(' ')[0]:'Sign in';$('.top-avatar').textContent=state.user?initials.slice(0,1):'V';$('#sidebar-account').innerHTML=`<div class="avatar">${esc(initials)}</div><div><strong>${esc(name)}</strong><small>${state.user?'Trips synced to your account':'Sign in to sync trips'}</small></div>`}
function render(){nav();$('#main').innerHTML=(state.view==='saved'?savedView():state.view==='explore'?exploreView():state.plan?resultView():studioView());$('#main').classList.remove('fade-in');void $('#main').offsetWidth;$('#main').classList.add('fade-in');wireView();wireImages()}
function previewNote(){return state.preview?'<div class="preview-note">Interactive preview · built-in planning runs in your browser. AI and live travel providers are available in the FastAPI app.</div>':''}
function destinationCard(d){return `<button class="destination-card" data-destination="${esc(d.id)}"><div class="cover">${picture(d.image,d.image_subject===d.name?d.name+' travel photograph':'Travel inspiration photo')}<span class="location-tag">${icon('pin')}${esc(d.country)}${d.image_subject!==d.name?' · illustrative photo':''}</span></div><div class="destination-info"><div><h3>${esc(d.name)}</h3><p>${esc(d.description)}</p></div><span class="round-button" aria-hidden="true">↗</span></div></button>`}
function studioView(){return `${previewNote()}<div class="page-head"><div><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h1>Where do you want to go?</h1><p>One request becomes a compared, costed, day-by-day journey.</p></div><span class="date-caption">${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</span></div>${state.error?`<div class="error-message" role="alert">${esc(state.error)}</div>`:''}<div class="studio-grid"><form id="plan-form" class="prompt-panel"><label class="panel-heading" for="trip-prompt">${icon('spark')}Your adventure, in a few words</label><textarea id="trip-prompt" maxlength="3000" minlength="8" required aria-describedby="prompt-help">${esc(state.prompt)}</textarea><div class="prompt-bottom"><div class="mini-tags"><span class="mini-tag">${icon('plane')} Flights + trains</span><span class="mini-tag">${icon('bed')} Value stays</span><span class="mini-tag">${icon('wallet')} Total budget</span></div><div class="prompt-actions"><button class="button yellow" type="submit">Launch 7 agents ${icon('arrow')}</button><button class="button ghost" type="button" data-action="details">${icon('settings')}Trip details${Object.keys(state.overrides).length?' · set':''}</button></div><p class="prompt-footnote" id="prompt-help">Tell us where, when, who’s coming and your total budget in ₹. Live availability is shown only when a provider returns it.</p></div></form><div class="photo-feature">${picture('/assets/bali.jpg','Kelingking Beach on Nusa Penida, Bali','','fetchpriority="high"')}<div class="feature-top"><span class="photo-pill">A LITTLE INSPIRATION</span><span class="photo-counter">08° S / 115° E</span></div><div class="feature-bottom"><div><small>BALI, INDONESIA</small><h2>Find your<br>island time.</h2><p>Ocean air. Slow mornings. Room to wander.</p></div><button class="round-button" data-destination="bali" aria-label="Plan a Bali trip">${icon('arrow')}</button></div></div></div><div class="studio-strip"><div class="strip-item">${icon('spark')}<div>Seven specialist agents<small>Route, stay, mobility, itinerary, budget</small></div></div><div class="strip-item">${icon('wallet')}<div>No mystery math<small>Every estimate and trade-off is visible</small></div></div><div class="strip-item">${icon('save')}<div>Your trips follow you<small>Sign in to save across devices</small></div></div></div><section><div class="section-header"><div><h2>A few places to begin</h2><p>Pick a destination. Make it your own.</p></div><button class="text-button" data-nav="explore">Explore all ↗</button></div><div class="destination-grid">${['bali','tokyo','paris'].map(id=>destinationCard(state.catalog.find(d=>d.id===id))).join('')}</div></section>`}
function resultView(){const p=state.plan,b=p.brief;return `<div class="result-toolbar"><button class="back-button" data-action="new">${icon('back')}Trip studio</button><div class="toolbar-actions"><button class="button small secondary" data-action="details">${icon('settings')}Edit trip</button><button class="button small secondary" data-action="save">${icon('save')}${state.saved.some(s=>s.id===p.id)?'Save changes':'Save trip'}</button><button class="button small secondary" data-action="download">${icon('download')}JSON</button><button class="button small yellow" data-action="print">${icon('print')}Export PDF</button></div></div><div class="result-hero">${picture(p.destination.image,p.destination.image_subject||b.destination)}<span class="hero-photo-caption">${esc(p.destination.image_subject||b.destination)} · ${p.destination.image_source?link(p.destination.image_source,'Wikipedia ↗'):'Unsplash'}</span><div><span class="eyebrow">${p.recommendation?esc(p.recommendation.score)+'% PLAN FIT / ':''}${esc(p.destination.country)}</span><h1>${esc(b.destination)} awaits.</h1><p>${esc(p.recommendation?.headline||p.destination.tagline)}</p><div class="hero-chips"><span class="chip">${icon('calendar')}${esc(tripDates(b))}</span><span class="chip">${icon('people')}${b.travelers} ${b.travelers===1?'traveler':'travelers'}</span><span class="chip">${icon('clock')}${esc(b.pace)} pace</span><span class="chip">${icon('plane')}From ${esc(b.origin)}</span></div></div><div class="hero-aside"><span>TRIP ESTIMATE</span><strong>${money(p.budget.total)}</strong><small>for everyone · ${b.days} days</small></div></div><div class="result-tabs" role="tablist" aria-label="Trip views">${[['overview','compass','Overview'],['itinerary','calendar','Day-by-day'],['stays','bed','Travel options'],['budget','wallet','Budget'],['copilot','spark','Travel copilot']].map(([id,i,label])=>`<button class="tab-button ${state.tab===id?'active':''}" id="tab-${id}" role="tab" aria-selected="${state.tab===id}" aria-controls="trip-tab-content" tabindex="${state.tab===id?0:-1}" data-tab="${id}">${icon(i)}${label}</button>`).join('')}</div><div id="trip-tab-content" role="tabpanel" aria-labelledby="tab-${state.tab}">${state.tab==='overview'?overviewView():state.tab==='itinerary'?itineraryView():state.tab==='stays'?staysView():state.tab==='budget'?budgetView():copilotView()}</div>`}
function budgetMini(){const b=state.plan.budget;return `<div class="panel"><div class="panel-title"><h2>Your trip, in numbers</h2><span class="tag ${b.remaining>=0?'yellow':'red'}">${b.remaining>=0?'WITHIN BUDGET':'OVER BUDGET'}</span></div><div class="budget-number">${money(b.total)}</div><p class="budget-target">estimated total / ${money(b.target)} budget</p><div class="budget-track ${b.remaining<0?'over':''}"><div style="width:${Math.min(100,b.total/b.target*100)}%"></div></div><p class="budget-remaining ${b.remaining<0?'over':''}">${money(Math.abs(b.remaining))} ${b.remaining>=0?'left in your budget':'over your budget'}</p><div class="budget-mini-items">${b.items.map((x,i)=>`<div class="budget-mini-item"><span><i class="budget-dot" style="background:${COLORS[i]}"></i>${esc(x.label)}</span><strong>${money(x.amount)}</strong></div>`).join('')}</div><p class="tiny-note">Planning estimates for ${state.plan.brief.travelers} people. Includes a 15% contingency. Not a supplier quote.</p></div>`}
function notes(){return `<div class="notice"><strong>A good plan leaves room for real life.</strong><ul>${state.plan.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`}
function agentBoard(){const p=state.plan;if(!p.agents?.length)return'';return `<section class="agent-console"><div class="agent-console-head"><div><span class="eyebrow">MULTI-AGENT MISSION CONTROL</span><h2>${esc(p.recommendation?.headline||'Your specialist team has finished')}</h2><p>${esc(p.recommendation?.reason||'Each specialist checked one part of the journey.')}</p></div><div class="fit-score"><strong>${esc(p.recommendation?.score||'—')}</strong><span>PLAN FIT</span></div></div><div class="agent-grid">${p.agents.map((a,i)=>`<article class="agent-card"><div class="agent-number">0${i+1}</div><div><div class="agent-name"><strong>${esc(a.name)}</strong><span>${esc(a.mode)}</span></div><p>${esc(a.summary)}</p></div></article>`).join('')}</div></section>`}
function overviewView(){const p=state.plan;return `${agentBoard()}<div class="result-layout"><div><div class="panel"><div class="panel-title"><h2>Your journey at a glance</h2><span class="tag blue">${p.days.length} DAYS / ${esc(p.brief.pace.toUpperCase())}</span></div>${p.days.map(d=>`<div class="day-preview"><div class="day-number"><small>DAY</small><strong>${String(d.day).padStart(2,'0')}</strong></div><div><h3>${esc(d.title)}</h3><p>${esc(d.date?dateLabel(d.date,{day:'numeric',month:'short',weekday:'short'}):`Day ${d.day}`)} · ${d.items.filter(i=>!['rest','travel','free'].includes(i.category)).length} suggested stops</p></div><button class="icon-button" data-day="${d.day}" aria-label="See day ${d.day}">${icon('right')}</button></div>`).join('')}</div><div class="panel"><div class="panel-title"><h2>Get your bearings</h2>${icon('map')}</div>${mapPanel()}<div class="map-caption"><span>Destination overview · routes are not calculated</span>${link(mapURL(p.brief.destination),'Open map ↗')}</div></div></div><aside class="overview-sidebar">${budgetMini()}<div class="panel"><div class="panel-title"><h2>Leave room to wander</h2>${icon('sun')}</div>${picture(p.destination.id==='bali'?'/assets/terraces.jpg':p.destination.image,p.destination.id==='bali'?'Tegallalang rice terraces, Bali':p.destination.image_subject||p.brief.destination,'overview-image')}<p class="inspiration-quote">The best part of a trip<br>isn’t always on the itinerary.</p><p class="tiny-note">Skip an optional stop, linger over lunch, or take the scenic way back.</p></div><div class="panel"><div class="panel-title"><h2>Weather window</h2>${icon('sun')}</div>${weatherPanel()}</div></aside></div>${notes()}`}
function mapPanel(){const d=state.plan.destination;if(!Number.isFinite(d.lat)||!Number.isFinite(d.lon))return `<p class="muted">Open the map to confirm the destination and plan your routes.</p>`;const delta=d.id==='bali'?.22:.08;const params=new URLSearchParams({bbox:[d.lon-delta,d.lat-delta,d.lon+delta,d.lat+delta].join(','),layer:'mapnik',marker:[d.lat,d.lon].join(',')});return `<iframe class="map-frame" title="Map of ${esc(d.name)}" src="https://www.openstreetmap.org/export/embed.html?${esc(params.toString())}" loading="lazy" referrerpolicy="no-referrer"></iframe>`}
function weatherPanel(){const w=state.plan.weather;if(!w?.time?.length)return `<p class="muted">Your weather check comes closer to departure.</p><p class="tiny-note">${esc(state.plan.weather_note)} ${state.preview?'Live weather is available through the FastAPI app.':'No forecast was returned for these dates.'}</p>`;return w.time.slice(0,7).map((date,i)=>`<div class="weather-day"><span>${dateLabel(date,{day:'numeric',month:'short'})}</span><strong>${w.temperature_2m_min?.[i]??'—'}° / ${w.temperature_2m_max?.[i]??'—'}°C</strong><span>${w.precipitation_probability_max?.[i]??'—'}% rain</span></div>`).join('')+'<p class="tiny-note">Forecast: Open-Meteo. Only dates returned by the provider are shown.</p>'}
function itineraryView(){const p=state.plan,d=p.days[state.day-1]||p.days[0];return `<div class="timeline-controls"><div class="day-selector">${p.days.map(x=>`<button class="day-button ${d.day===x.day?'active':''}" data-day="${x.day}" aria-pressed="${d.day===x.day}">Day ${String(x.day).padStart(2,'0')}</button>`).join('')}</div></div><div class="result-layout"><section class="panel"><div class="day-heading"><div><span class="eyebrow">${esc(dateLabel(d.date))} / DAY ${d.day}</span><h2>${esc(d.title)}</h2><p>${icon('pin')}${esc(d.area)}</p></div><span class="tag yellow">${esc(p.brief.pace.toUpperCase())} PACE</span></div>${d.items.map((a,i)=>`<div class="timeline-item"><span class="timeline-time">${esc(a.time)}</span><span class="timeline-dot"></span><article class="activity-card ${a.category==='rest'?'rest':''} ${a.skipped?'skipped':''}"><div class="activity-heading"><h3>${esc(a.title)}</h3><span class="tag ${a.category==='rest'?'yellow':''}">${esc(a.category)}</span></div><p>${esc(a.description)}</p><div class="activity-meta"><span>${esc(a.duration)}</span>${a.map_url?link(a.map_url,`${icon('pin')}Verify on map`):''}</div>${a.optional?`<label class="activity-toggle"><input type="checkbox" data-skip="${i}" ${a.skipped?'':'checked'}>Keep this optional stop</label>`:''}</article></div>`).join('')}<p class="tiny-note">${esc(d.note)} Removing an optional stop does not recalculate the activity allowance.</p></section><aside>${budgetMini()}<div class="panel"><div class="panel-title"><h2>A few things to pack</h2>${icon('bag')}</div><div class="checklist">${p.packing.map((x,i)=>`<label><input type="checkbox" data-pack="${i}" ${p.packed?.includes(i)?'checked':''}>${esc(x)}</label>`).join('')}</div><p class="tiny-note">A starting checklist. Add destination and activity essentials before leaving.</p></div></aside></div>`}
function staysView(){const p=state.plan;return `<div class="section-header"><div><h2>Find your kind of stay</h2><p>${p.hotels.some(h=>h.real_property)?'Property discovery from Google Maps. Availability and rates need checking.':'Neighbourhoods and stay styles to guide your search. Photos are illustrative.'}</p></div><span class="tag blue">${p.budget.rooms} ROOM(S) / ${p.budget.nights} NIGHTS</span></div>${p.budget.nights===0?'<div class="notice">This is a day trip, so your budget includes no overnight accommodation.</div>':`<div class="hotels-grid">${p.hotels.map(h=>hotelCard(h)).join('')}</div>`}<div class="transport-grid"><section class="panel"><div class="transport-header"><div class="transport-icon">${icon('plane')}</div><div><h3>The way there</h3><p>Flights for ${p.brief.travelers} people · compare before booking</p></div></div><div class="flight-route"><span>${esc(p.brief.origin)}</span><div class="flight-line">${icon('plane')}</div><span>${esc(p.brief.destination)}</span></div><div class="hotel-price">${money(p.budget.items.find(x=>x.id==='flights').amount)} <small>estimated total</small></div><p class="tiny-note">Airfare allowance only. Search links do not guarantee a matching fare, schedule or baggage allowance.</p>${p.flights.map(f=>`<div class="flight-offer"><span class="tag ${f.live?'blue':'red'}">${esc(f.source)}</span><strong>${money(f.price)}</strong><span>${f.travelers} traveler(s) · ${esc(f.currency)}</span>${f.itineraries.map(r=>`<p>${r.segments.map(s=>`${esc(s.from)} → ${esc(s.to)} · ${esc(s.carrier)} ${esc(s.number)}`).join(' / ')}</p><p>${esc(r.duration)} · ${esc(r.segments[0]?.departure||'')}</p>`).join('')}<p>Retrieved ${esc(dateLabel(p.created_at.slice(0,10)))}. Reprice before booking. Not included in the estimate.</p></div>`).join('')}${link(p.flight_search_url,`Compare flights ${icon('arrow')}`,'button secondary full')}</section><section class="panel"><div class="transport-header"><div class="transport-icon">${icon('map')}</div><div><h3>Get around, with ease</h3><p>Airport transfers, local rides and getting between stops</p></div></div><p class="muted">Group your day around one neighbourhood where possible. Compare a driver, public transport and local ride services for your actual route.</p><div class="hotel-price">${money(p.budget.items.find(x=>x.id==='transport').amount)} <small>trip allowance</small></div><p class="tiny-note">Travel times are not calculated. Leave a margin for traffic and check local availability and operator terms.</p>${link(p.transfer_url,`Find local transfers ${icon('arrow')}`,'button secondary full')}</section></div><div class="notice"><strong>You’re in control of every booking.</strong> These buttons open external providers. VoyageOS does not reserve rooms, purchase tickets or process payments.</div>`}
function hotelCard(h){return `<article class="hotel-card"><div class="hotel-image">${picture(h.image||'/assets/hotel.jpg',h.real_property&&h.image?h.name:'Illustrative accommodation inspiration')}<span class="tag">${h.real_property?'PROPERTY DISCOVERY':'STAY INSPIRATION'}</span><span class="photo-label">${h.real_property&&h.image?'Property photo · Google Maps':'Illustrative photo · Unsplash'}</span></div><div class="hotel-body"><h3>${esc(h.name)}</h3><div class="hotel-area">${esc(h.area)}</div><p>${esc(h.description)}</p><div class="price-block">${h.real_property?`<div class="hotel-provider">${h.rating?`${icon('star')} ${h.rating} / 5 · ${h.reviews??0} reviews`:'Check recent reviews on Google Maps'}<br><small>Room rates not provided</small></div>`:`<div class="hotel-price">~${money(h.nightly_estimate)} <small>/ room / night</small></div><span class="photo-source">Illustrative allowance, not a property quote</span>`}</div>${link(h.url,`${h.real_property?'View on Google Maps':'Explore stays'} ${icon('arrow')}`,'button secondary')}${(h.photo_authors||[]).map(a=>`<div class="hotel-attribution">Photo: ${link(a.uri,esc(a.displayName))}</div>`).join('')}${(h.attributions||[]).map(a=>`<div class="hotel-attribution">${link(a.providerUri,esc(a.provider))}</div>`).join('')}</div></article>`}
function budgetView(){const b=state.plan.budget;let position=0;const segments=b.items.map((x,i)=>{let start=position;position+=b.total?x.amount/b.total*100:0;return `${COLORS[i]} ${start}% ${position}%`}).join(',');return `<div class="section-header"><div><h2>Every rupee has a place.</h2><p>One transparent estimate for the whole group, including a contingency.</p></div><span class="tag">INR / ESTIMATES</span></div><div class="budget-layout"><section class="panel"><div class="panel-title"><h2>Your estimated total</h2>${icon('wallet')}</div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${segments})" role="img" aria-label="Budget breakdown; exact amounts are listed alongside"><div class="donut-inner"><strong>${money(b.total)}</strong><small>for ${state.plan.brief.travelers} travelers</small></div></div></div><div class="budget-mini-item"><span>Your budget</span><strong>${money(b.target)}</strong></div><div class="budget-mini-item"><span>Per person estimate</span><strong>${money(b.per_person)}</strong></div><div class="budget-track ${b.remaining<0?'over':''}"><div style="width:${Math.min(100,b.total/b.target*100)}%"></div></div><p class="budget-remaining ${b.remaining<0?'over':''}">${money(Math.abs(b.remaining))} ${b.remaining>=0?'left in your budget':'over your budget'}</p><div class="insight-box"><h3>${b.remaining>=0?'A little breathing room.':'Let’s make the numbers work.'}</h3><p>${b.remaining>=0?'Keep the remaining budget for unexpected costs. Estimated prices can change significantly by date and availability.':'Try value accommodation, fewer nights or different travel dates. Change Trip details to compare a new plan.'}</p><button class="button small secondary full" data-action="details">Adjust trip details</button></div></section><section class="panel"><div class="panel-title"><h2>The full breakdown</h2><span class="tag blue">ALL TRAVELERS</span></div>${b.items.map((x,i)=>`<div class="budget-breakdown-row"><div class="budget-breakdown-head"><span><i class="budget-dot" style="background:${COLORS[i]}"></i>${esc(x.label)}</span><strong>${money(x.amount)}</strong></div><p>${esc(x.detail)}</p><div class="category-bar"><div style="width:${b.total?x.amount/b.total*100:0}%;background:${COLORS[i]}"></div></div></div>`).join('')}<p class="tiny-note">${esc(b.basis)}</p></section></div>`}
function copilotView(){return `<div class="chat-layout"><section class="panel chat-panel"><div class="chat-header"><h2>${icon('spark')} Your travel copilot</h2><span>${state.preview?'Preview assistant':state.config?.ai?'Groq connected':'Built-in assistant'}</span></div><div class="messages" id="messages" role="log" aria-live="polite"><div class="message"><small>VOYAGEOS</small>Your ${esc(state.plan.brief.destination)} plan is ready to make your own. Ask about the budget, slowing things down, choosing a stay, or rainy-day alternatives.</div>${messageHTML()}</div><form class="chat-input-form" id="chat-form"><input name="message" aria-label="Ask your travel copilot" placeholder="What if it rains?" required maxlength="1500" autocomplete="off"><button class="button yellow" type="submit" ${state.chatBusy?'disabled':''} aria-label="Send message">${icon('arrow')}</button></form></section><aside><div class="panel"><span class="eyebrow">A LITTLE HELP, ANYTIME</span><h2>Make a good trip<br>feel like your trip.</h2>${['How can I reduce the budget?','Can we make the trip more relaxed?','Which area should we stay in?','What if it rains?'].map(q=>`<button class="suggested-question" data-question="${esc(q)}">${esc(q)}<span>↗</span></button>`).join('')}<p class="tiny-note">Copilot replies are advice. Use Edit trip to apply changes and regenerate. It cannot book or verify live entry requirements.</p></div><div class="panel"><div class="panel-title"><h2>Your current brief</h2>${icon('compass')}</div><p class="muted">${esc(state.plan.brief.destination)} · ${state.plan.brief.days} days<br>${state.plan.brief.travelers} travelers · ${money(state.plan.brief.budget)}<br>${esc(state.plan.brief.pace)} pace · ${esc(state.plan.brief.comfort)} stays</p></div></aside></div>`}
function messageHTML(){return state.messages.map(m=>`<div class="message ${m.role==='user'?'user':''}">${m.role!=='user'?`<small>VOYAGEOS${m.mode?' / '+esc(m.mode.toUpperCase()):''}</small>`:''}${esc(m.content)}</div>`).join('')+(state.chatBusy?'<div class="message"><span class="spinner"></span> Thinking about your trip…</div>':'')}
function savedView(){return `<div class="page-head"><div><span class="eyebrow">GOOD PLANS DESERVE TO BE KEPT</span><h1>Your next adventures.</h1><p>Trips saved in this browser. Download a copy to keep or move them.</p></div><button class="button yellow small" data-action="new">New trip ${icon('arrow')}</button></div>${state.saved.length?`<div class="saved-grid">${state.saved.map(p=>`<article class="saved-card">${picture(p.destination.image,p.destination.image_subject||p.brief.destination)}<div class="saved-card-body"><span class="eyebrow">${esc(p.destination.country)}</span><h2>${esc(p.brief.destination)}</h2><p>${esc(tripDates(p.brief))}<br>${p.brief.travelers} travelers · ${p.brief.days} days · ${esc(p.brief.pace)}</p><span class="tag blue">${money(p.budget.total)} ESTIMATE</span><div class="saved-card-actions"><button class="button secondary small" data-open="${esc(p.id)}">Open itinerary ${icon('arrow')}</button><button class="icon-button" data-delete="${esc(p.id)}" aria-label="Delete ${esc(p.brief.destination)} trip">${icon('trash')}</button></div></div></article>`).join('')}</div>`:`<div class="empty-state">${icon('save')}<h2>A world of plans ahead.</h2><p>Your saved trips will live here. Build a trip, then select Save trip to come back to it whenever inspiration strikes.</p><button class="button yellow" data-action="new">Plan an adventure ${icon('arrow')}</button></div>`}`}
function exploreView(){return `<div class="page-head"><div><span class="eyebrow">FOLLOW YOUR CURIOSITY</span><h1>Somewhere new is calling.</h1><p>Start with a destination. Set your budget, dates and pace.</p></div></div><div class="search-row"><input id="destination-search" class="search-input" placeholder="Search destinations…" aria-label="Search built-in destinations"></div><div class="destination-grid explore-grid" id="explore-results">${state.catalog.map(destinationCard).join('')}</div><div class="notice">Planning somewhere else? Enter any destination in Trip studio. Groq adds destination-specific suggestions beyond this built-in catalog; preview mode creates a flexible outline.</div>`}
function wireImages(){document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{if(!img.dataset.failed){img.dataset.failed='true';img.src='/assets/terraces.jpg';img.alt='Travel inspiration photo';const caption=img.closest('.result-hero')?.querySelector('.hero-photo-caption');if(caption)caption.textContent='Travel inspiration · Unsplash';const label=img.closest('.hotel-image')?.querySelector('.photo-label');if(label)label.textContent='Illustrative photo · Unsplash'}},{once:true}))}
function wireView(){
 $('#plan-form')?.addEventListener('submit',e=>{e.preventDefault();state.prompt=$('#trip-prompt').value.trim();generate()});
 $('#trip-prompt')?.addEventListener('input',e=>state.prompt=e.target.value);
 $('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();const input=e.target.elements.message;sendChat(input.value);input.value=''});
 $('#destination-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();const found=state.catalog.filter(d=>(d.name+' '+d.country).toLowerCase().includes(q));$('#explore-results').innerHTML=found.length?found.map(destinationCard).join(''):'<p class="muted">No catalog match. You can enter this destination in Trip studio.</p>';wireImages()});
 $('.result-tabs')?.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=['overview','itinerary','stays','budget','copilot'];let i=ids.indexOf(state.tab);i=e.key==='Home'?0:e.key==='End'?4:(i+(e.key==='ArrowRight'?1:4))%5;state.tab=ids[i];render();$('#tab-'+state.tab).focus()});
}
function showDetails(){
 let base={};try{base=parsePrompt(state.prompt,state.catalog)}catch{}const b={...base,...(state.plan?.brief||{}),...state.overrides};
 const input=(name,label,type='text',attrs='')=>`<div class="form-field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(b[name]??'')}" ${attrs}></div>`;
 const select=(name,label,options)=>`<div class="form-field"><label for="field-${name}">${label}</label><select id="field-${name}" name="${name}"><option value="">From your request</option>${options.map(x=>`<option value="${x}" ${b[name]===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></div>`;
 $('#detail-fields').innerHTML=input('destination','Destination','text','maxlength="100" placeholder="Bali, Tokyo, anywhere…"')+input('origin','Departure city','text','maxlength="100" placeholder="Kolkata"')+input('start_date','Departure date','date',`min="${today()}"`)+input('days','Days','number','min="1" max="30" step="1" placeholder="6"')+input('travelers','Travelers','number','min="1" max="20" step="1" placeholder="2"')+input('budget','Total budget (INR)','number','min="1000" max="10000000" step="1" placeholder="140000"')+select('pace','Travel pace',['relaxed','balanced','packed'])+select('comfort','Stay comfort',['value','comfort','luxury']);
 $('#details-form button[type="submit"]').innerHTML=state.plan?`Regenerate my trip ${icon('arrow')}`:`Apply details ${icon('check')}`;$('#details-dialog').showModal();
}
$('#details-form').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const overrides={};for(const [key,val] of Object.entries(values))if(String(val).trim())overrides[key]=['days','travelers','budget'].includes(key)?Number(val):String(val).trim();if(state.plan)overrides.interests=state.plan.brief.interests;state.overrides=overrides;$('#details-dialog').close();if(state.plan)generate();else{render();toast('Trip details applied. Ready when you are.')}});
function stageView(stage='Intent',detail='Intent Agent is reading your travel brief'){return `<div class="planning-stage"><div class="planning-orb">${icon('spark')}</div><span class="eyebrow" style="margin-top:30px">SEVEN SPECIALISTS / ONE JOURNEY</span><h1>Your agent team<br>is comparing the trip.</h1><p class="stage-detail" id="stage-detail">${esc(detail)}</p><div class="stage-list">${['Intent','Route','Stay','Mobility','Itinerary','Budget','Critic'].map(s=>`<span class="stage-pill ${s===stage?'active':''}" data-stage="${s}">${s}</span>`).join('')}</div><button class="button small ghost" data-action="cancel">Cancel planning</button></div>`}
function setStage(info){if($('#stage-detail'))$('#stage-detail').textContent=info.detail;document.querySelectorAll('[data-stage]').forEach(n=>n.classList.toggle('active',n.dataset.stage===info.stage))}
async function generate(){
 if(state.busy)return;state.busy=true;state.error='';state.view='studio';state.abort=new AbortController();nav();$('#main').innerHTML=stageView();window.scrollTo({top:0,behavior:'smooth'});
 const payload={prompt:state.prompt,...state.overrides};
 try{let result;if(state.preview){await new Promise(requestAnimationFrame);setStage({stage:'Critic',detail:'Seven local specialists checked route, stays, movement, pace and cost'});result=makeLocalPlan(payload,state.catalog)}else{result=await streamPlan(payload,state.abort.signal)}
 if(state.abort.signal.aborted)return;
 result.prompt=state.prompt;result.request=payload;state.plan=result;state.messages=[];state.day=1;state.tab='overview';state.overrides={};render();toast('Your itinerary is ready. Make it yours.');
 }catch(err){if(err.name==='AbortError')toast('Planning cancelled.');else state.error=err.message||'We could not plan this trip. Please try again.';if(state.plan){render();if(state.error)toast(state.error)}else render()}
 finally{state.busy=false;state.abort=null}
}
async function streamPlan(payload,signal){const response=await fetch('/api/plan/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal});if(!response.ok){let body=await response.json().catch(()=>({}));throw Error(errorDetail(body)||`Planner returned ${response.status}. Please try again.`)}if(!response.body)throw Error('Streaming is unavailable in this browser.');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',result;while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let index;while((index=buffer.indexOf('\n\n'))!==-1){const frame=buffer.slice(0,index);buffer=buffer.slice(index+2);let type='',data='';for(const line of frame.split('\n')){if(line.startsWith('event:'))type=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim()}if(!data)continue;const obj=JSON.parse(data);if(type==='progress')setStage(obj);else if(type==='result')result=obj;else if(type==='error')throw Error(obj.detail)}}if(!result)throw Error('The connection ended before your plan was ready. Try again.');return result}
function errorDetail(body){return typeof body.detail==='string'?body.detail:Array.isArray(body.detail)?body.detail.map(d=>d.msg).join('. '):''}
async function sendChat(message){message=message.trim();if(!message||state.chatBusy||!state.plan)return;state.messages.push({role:'user',content:message});state.chatBusy=true;render();try{let response;if(state.preview)response={answer:localChat(message,state.plan),mode:'preview'};else{const raw=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,brief:state.plan.brief,history:state.messages.slice(-9,-1).map(({role,content})=>({role,content}))}),signal:AbortSignal.timeout(50000)});response=await raw.json();if(!raw.ok)throw Error(errorDetail(response)||'The copilot is unavailable. Please try again.')}state.messages.push({role:'assistant',content:response.answer,mode:response.mode})}catch(err){state.messages.push({role:'assistant',content:err.name==='TimeoutError'?'The copilot took too long. Please try again.':err.message,mode:'notice'})}finally{state.chatBusy=false;if(state.view==='studio'&&state.tab==='copilot'){render();const area=$('#messages');if(area)area.scrollTop=area.scrollHeight}}}
function saveTrip(){if(!state.plan)return;const old=state.saved.findIndex(s=>s.id===state.plan.id);const previous=state.saved.slice();const copy=structuredClone(state.plan);if(old>=0)state.saved[old]=copy;else state.saved.unshift(copy);state.saved=state.saved.slice(0,30);if(persist()){toast('Saved to this browser.');render()}else state.saved=previous}
function downloadTrip(){const blob=new Blob([JSON.stringify(state.plan,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`VoyageOS-${state.plan.brief.destination.replace(/[^a-z0-9_-]/gi,'-')}-${state.plan.brief.days}days.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Trip downloaded as JSON.')}
function printTrip(){const p=state.plan;$('.print-view')?.remove();const section=document.createElement('section');section.className='print-view';section.innerHTML=`<header><p>VOYAGEOS AI / YOUR TRAVEL PLAN</p><h1>${esc(p.brief.destination)} · ${p.brief.days} days</h1><p>${esc(tripDates(p.brief))} · ${p.brief.travelers} traveler(s) · From ${esc(p.brief.origin)}</p><p>${esc(p.brief.pace)} pace · ${money(p.budget.total)} estimated total</p></header><h2>Budget estimate (INR)</h2><table><thead><tr><th>Category</th><th>Estimate</th><th>Basis</th></tr></thead><tbody>${p.budget.items.map(x=>`<tr><td>${esc(x.label)}</td><td>${money(x.amount)}</td><td>${esc(x.detail)}</td></tr>`).join('')}<tr><th>Total</th><th>${money(p.budget.total)}</th><td>Target ${money(p.budget.target)}</td></tr></tbody></table><p class="print-small">${esc(p.budget.basis)}</p><h2>Your day-by-day itinerary</h2>${p.days.map(d=>`<article class="print-day"><h2>Day ${d.day}: ${esc(d.title)}</h2><p>${esc(dateLabel(d.date))}</p>${d.items.map(a=>`<h3>${esc(a.time)} · ${esc(a.title)}${a.skipped?' (skipped)':''}</h3><p>${esc(a.description)}</p><p class="print-small">${esc(a.area)} · ${esc(a.duration)}${a.optional?' · optional':''}${a.map_url?' · '+link(a.map_url,'Map search'):''}</p>`).join('')}<p class="print-small">${esc(d.note)}</p></article>`).join('')}<h2>Stays & transport</h2>${p.hotels.map(h=>`<h3>${esc(h.name)}</h3><p>${esc(h.description)}</p><p>${h.real_property?'Property discovery; rates not returned.':`${money(h.nightly_estimate)} / room / night — illustrative estimate.`} ${link(h.url,'Open provider')}</p>`).join('')}<p>${link(p.flight_search_url,'Compare flights')} · ${link(p.transfer_url,'Find transfers')}</p><h2>Before you book</h2><ul>${p.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul><p class="print-small">Created ${esc(dateLabel(p.created_at.slice(0,10)))}. No bookings have been made. For personal planning only.</p>`;document.body.append(section);window.print()}
async function credits(){const dialog=$('#credits-dialog');$('#credits-content').innerHTML='<p class="muted">Loading photo credits…</p>';dialog.showModal();try{const raw=await fetch('/assets/photo-credits.json');const data=await raw.json();const rows=Array.isArray(data)?data:data.assets||data.images||data.photos||[];$('#credits-content').innerHTML=`<p class="muted">Travel photography from Unsplash. Stay inspiration photos are illustrative.</p><div class="credits-list">${rows.map(x=>`<div>${link(x.source_page||x.source_page_url||x.source_url||x.page_url||'https://unsplash.com/',esc(x.author||x.photographer||x.title||x.subject||'View original photograph'))}</div>`).join('')}</div><p>${link('https://unsplash.com/license','Unsplash License')}</p><p class="credit-note">Live destination context may use Wikipedia and Wikimedia Commons; follow the image source on the trip. Weather and geocoding: ${link('https://open-meteo.com/','Open-Meteo / GeoNames')}. Map tiles: ${link('https://www.openstreetmap.org/copyright','OpenStreetMap contributors')}.</p><p class="credit-note">Google Maps property data, photos and author credits appear when configured. Budgets are illustrative estimates; map and provider links do not confirm availability. Saved trips remain in this browser.</p>`}catch{$('#credits-content').innerHTML=`<p>Photos: Unsplash. ${link('https://unsplash.com/license','View license')}.</p>`}}
document.addEventListener('click',e=>{
 if(e.target.closest('a.brand')){e.preventDefault();if(state.busy||state.chatBusy)return;state.view='studio';render();return}
 const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return}
 const button=e.target.closest('button');if(!button)return;
 if(button.dataset.nav){if(state.busy||state.chatBusy){toast('Wait for the current request to finish.');return}state.view=button.dataset.nav;state.error='';render();window.scrollTo({top:0,behavior:'smooth'});return}
 if(button.dataset.destination){if(state.busy)return;const d=state.catalog.find(d=>d.id===button.dataset.destination);state.plan=null;state.overrides={};state.prompt=`Plan a 6-day trip to ${d.name} for 2 people from Kolkata. Budget ₹${d.id==='paris'||d.id==='tokyo'?'2.5 lakh':'1.4 lakh'}. We like ${d.id==='bali'?'beaches, nature and good food':'culture, nature and good food'}. Keep it relaxed.`;state.view='studio';state.error='';render();$('#trip-prompt')?.focus();return}
 if(button.dataset.tab){state.tab=button.dataset.tab;render();return}
 if(button.dataset.day){state.day=Number(button.dataset.day);state.tab='itinerary';render();return}
 if(button.dataset.question){sendChat(button.dataset.question);return}
 if(button.dataset.open){state.plan=structuredClone(state.saved.find(p=>p.id===button.dataset.open));state.prompt=state.plan.prompt||`Plan a trip to ${state.plan.brief.destination}`;state.overrides={};state.messages=[];state.view='studio';state.tab='overview';state.day=1;render();return}
 if(button.dataset.delete){state.deleteId=button.dataset.delete;$('#delete-dialog').showModal();return}
 const action=button.dataset.action;if(!action)return;
 if(action==='cancel'){state.abort?.abort();return}
 if(state.busy||state.chatBusy){toast('Wait for the current request to finish.');return}
 if(action==='details')showDetails();else if(action==='save')saveTrip();else if(action==='download')downloadTrip();else if(action==='print')printTrip();else if(action==='new'){state.plan=null;state.view='studio';state.overrides={};state.error='';render();window.scrollTo({top:0,behavior:'smooth'})}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-pack]')){const i=Number(e.target.dataset.pack);state.plan.packed=state.plan.packed||[];state.plan.packed=e.target.checked?[...new Set([...state.plan.packed,i])]:state.plan.packed.filter(n=>n!==i)}if(e.target.matches('[data-skip]')){const i=Number(e.target.dataset.skip);state.plan.days[state.day-1].items[i].skipped=!e.target.checked;e.target.closest('.activity-card').classList.toggle('skipped',!e.target.checked)}});
$('#confirm-delete').addEventListener('click',deleteSavedTrip);
$('#credits-btn').addEventListener('click',credits);
async function init(){loadSaved();try{const [catalog,config]=await Promise.allSettled([fetch('/catalog.json').then(r=>{if(!r.ok)throw Error('Destination catalog is unavailable.');return r.json()}),fetch('/api/config',{signal:AbortSignal.timeout(6000)}).then(r=>{if(!r.ok)throw Error('No API');return r.json()})]);if(catalog.status!=='fulfilled')throw catalog.reason;state.catalog=catalog.value;if(config.status==='fulfilled'&&config.value.service==='voyageos'){state.config=config.value;state.preview=false}$('#connection').textContent=state.preview?'Preview planner':state.config.ai?'AI planner connected':'Built-in planner';render()}catch(err){$('#main').innerHTML=`<div class="error-message">${esc(err.message)} Reload the page to try again.</div>`}}
async function apiJSON(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});if(response.status===204)return null;const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(errorDetail(data)||`Request failed (${response.status}).`);return data}
function showAuth(mode=state.user?'account':'login'){state.authMode=mode;renderAuth();const dialog=$('#auth-dialog');if(!dialog.open)dialog.showModal()}
function renderAuth(){const title=$('#auth-title'),content=$('#auth-content');if(state.preview){title.textContent='Account preview';content.innerHTML='<div class="auth-preview"><div class="planning-orb">'+icon('save')+'</div><h3>Account sync runs in the FastAPI app.</h3><p>Deploy this project on Render to create an account and keep trips in the server database. This hosted design preview keeps trips only in this browser.</p><button class="button yellow full" data-close="auth-dialog">Continue in preview</button></div>';return}if(state.user){title.textContent='Your VoyageOS account';content.innerHTML=`<div class="account-card"><div class="account-avatar">${esc(state.user.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}</div><h3>${esc(state.user.name)}</h3><p>${esc(state.user.email)}</p><div class="account-stat"><strong>${state.saved.length}</strong><span>saved ${state.saved.length===1?'trip':'trips'}</span></div><button class="button secondary full" data-auth-action="logout">Sign out</button></div>`;return}const register=state.authMode==='register';title.textContent=register?'Create your account':'Welcome back';content.innerHTML=`<div class="auth-switch" role="tablist"><button class="${register?'':'active'}" data-auth-mode="login" role="tab" aria-selected="${!register}">Sign in</button><button class="${register?'active':''}" data-auth-mode="register" role="tab" aria-selected="${register}">Create account</button></div><form id="auth-form" class="auth-form">${register?'<div class="form-field"><label for="auth-name">Name</label><input id="auth-name" name="name" minlength="2" maxlength="60" autocomplete="name" required placeholder="Ayush Shaw"></div>':''}<div class="form-field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" autocomplete="email" maxlength="200" required placeholder="you@example.com"></div><div class="form-field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="8" maxlength="128" required placeholder="At least 8 characters"></div><p id="auth-error" class="auth-error" role="alert"></p><button class="button yellow full" type="submit" ${state.authBusy?'disabled':''}>${state.authBusy?'Please wait…':register?'Create account':'Sign in'} ${icon('arrow')}</button><p class="auth-note">Your password is hashed before storage. The browser receives only a secure session cookie.</p></form>`}
async function submitAuth(form){if(state.authBusy)return;const values=Object.fromEntries(new FormData(form));state.authBusy=true;renderAuth();try{const route=state.authMode==='register'?'/api/auth/register':'/api/auth/login',data=await apiJSON(route,{method:'POST',body:JSON.stringify(values)});state.user=data.user;await loadCloudTrips();$('#auth-dialog').close();render();toast(`Welcome${state.user.name?' '+state.user.name.split(' ')[0]:''}. Your trips are synced.`);if(state.pendingSave){state.pendingSave=false;await saveTripV2()}}catch(err){state.authBusy=false;renderAuth();const node=$('#auth-error');if(node)node.textContent=err.message}finally{state.authBusy=false}}
async function logoutAccount(){try{await apiJSON('/api/auth/logout',{method:'POST'});state.user=null;state.saved=[];loadSaved();$('#auth-dialog').close();render();toast('Signed out.')}catch(err){toast(err.message)}}
async function loadCloudTrips(){if(state.preview||!state.user)return;try{const data=await apiJSON('/api/trips');state.saved=(data.trips||[]).map(x=>x.trip).filter(p=>p?.id&&p?.brief&&p?.budget);render()}catch(err){if(!/sign in/i.test(err.message))toast('Trips could not be synced right now.')}}
const saveTripLocal=saveTrip;
async function saveTripV2(){if(!state.plan)return;if(state.preview)return saveTripLocal();if(!state.user){state.pendingSave=true;showAuth('login');return}try{const data=await apiJSON('/api/trips',{method:'POST',body:JSON.stringify({trip:state.plan})}),copy=structuredClone(data.trip);const old=state.saved.findIndex(x=>x.id===copy.id);if(old>=0)state.saved[old]=copy;else state.saved.unshift(copy);render();toast('Trip saved to your account.')}catch(err){toast(err.message)}}
async function deleteSavedTrip(){const id=state.deleteId;if(!id)return;try{if(!state.preview&&state.user)await apiJSON('/api/trips/'+encodeURIComponent(id),{method:'DELETE'});state.saved=state.saved.filter(p=>p.id!==id);if(state.preview)persist();$('#delete-dialog').close();render();toast('Saved trip deleted.')}catch(err){toast(err.message)}}
function accountSavedView(){const location=state.preview?'this browser':state.user?'your account':'your account after sign-in';return `<div class="page-head"><div><span class="eyebrow">GOOD PLANS DESERVE TO BE KEPT</span><h1>Your next adventures.</h1><p>Trips saved in ${location}.${!state.preview&&!state.user?' Sign in to see them on every device.':''}</p></div><button class="button yellow small" data-action="new">New trip ${icon('arrow')}</button></div>${!state.preview&&!state.user?`<div class="empty-state">${icon('save')}<h2>Your trips are one sign-in away.</h2><p>Create a free project account or sign in to keep plans private and synced.</p><button class="button yellow" data-auth-mode="login">Sign in ${icon('arrow')}</button></div>`:state.saved.length?`<div class="saved-grid">${state.saved.map(p=>`<article class="saved-card">${picture(p.destination.image,p.destination.image_subject||p.brief.destination)}<div class="saved-card-body"><span class="eyebrow">${esc(p.destination.country)}</span><h2>${esc(p.brief.destination)}</h2><p>${esc(tripDates(p.brief))}<br>${p.brief.travelers} travelers · ${p.brief.days} days · ${esc(p.brief.pace)}</p><span class="tag blue">${money(p.budget.total)} ESTIMATE</span><div class="saved-card-actions"><button class="button secondary small" data-open="${esc(p.id)}">Open itinerary ${icon('arrow')}</button><button class="icon-button" data-delete="${esc(p.id)}" aria-label="Delete ${esc(p.brief.destination)} trip">${icon('trash')}</button></div></div></article>`).join('')}</div>`:`<div class="empty-state">${icon('save')}<h2>A world of plans ahead.</h2><p>Build a trip, then select Save trip to return to it whenever inspiration strikes.</p><button class="button yellow" data-action="new">Plan an adventure ${icon('arrow')}</button></div>`}`}
document.addEventListener('submit',e=>{if(e.target.id==='auth-form'){e.preventDefault();submitAuth(e.target)}});
document.addEventListener('click',e=>{const mode=e.target.closest('[data-auth-mode]');if(mode){showAuth(mode.dataset.authMode);return}const action=e.target.closest('[data-auth-action]');if(action?.dataset.authAction==='logout')logoutAccount()});
$('#account-btn').addEventListener('click',()=>showAuth());
$('#sidebar-account').addEventListener('click',()=>showAuth());

function travelView(){
 const p=state.plan,t=p.transport||{rail:{available:false,name:'Rail',label:'Not checked',description:'No rail result is available.',url:'#'},road:{available:false,name:'Road',label:'Not checked',description:'No road result is available.',url:'#'},cabs:[]};
 const flightCards=(p.flights||[]).map((f,i)=>`<article class="route-choice ${i===0?'recommended':''}"><div class="route-choice-top"><span class="tag ${i===0?'yellow':'blue'}">${esc(f.label||`Option ${i+1}`)}</span><span class="fit-mini">${esc(f.score||'—')} fit</span></div><strong>${money(f.estimate??f.price??0)}</strong><p>${esc(f.why||`${f.stops===0?'Direct':f.stops==null?'Compare route details':`${f.stops} stop(s)`}. Recheck baggage, timing and final fare.`)}</p>${(f.itineraries||[]).map(r=>`<small>${r.segments.map(s=>`${esc(s.from)} → ${esc(s.to)} · ${esc(s.carrier)} ${esc(s.number)}`).join(' / ')} · ${esc(r.duration)}</small>`).join('')}<span class="source-line">${esc(f.source||'Planning estimate')} · ${f.source_mode==='provider'?'provider result':'not live inventory'}</span>${link(f.url||p.flight_search_url,`${f.source_mode==='provider'?'Recheck fare':'Compare flights'} ${icon('arrow')}`,'button secondary full')}</article>`).join('');
 const surface=x=>`<article class="surface-card ${x.available?'':'muted-card'}"><div><span class="tag ${x.available?'blue':''}">${esc(x.label)}</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p></div>${x.estimate?`<strong>~${money(x.estimate)}</strong>`:''}${x.available?link(x.url,`Open ${esc(x.name)} ${icon('arrow')}`,'button secondary full'):''}</article>`;
 return `<div class="section-header"><div><span class="eyebrow">STAY AGENT</span><h2>Shortlisted places to stay</h2><p>${p.hotels.some(h=>h.real_property)?'Property discovery from Google Maps. Recheck availability and room rates.':'Neighbourhood-first stay searches with clearly marked planning estimates.'}</p></div><span class="tag blue">${p.budget.rooms} ROOM(S) / ${p.budget.nights} NIGHTS</span></div>${p.budget.nights===0?'<div class="notice">This is a day trip, so the plan includes no overnight stay.</div>':`<div class="hotels-grid">${p.hotels.map(h=>hotelCard(h)).join('')}</div>`}<section class="travel-lab"><div class="section-header"><div><span class="eyebrow">ROUTE AGENT</span><h2>Compare the way there</h2><p>Best fit, lowest-price target and fewer-stops target—ranked without hiding the source.</p></div><span class="tag yellow">${esc(p.brief.origin)} → ${esc(p.brief.destination)}</span></div><div class="route-choice-grid">${flightCards||'<div class="notice">No flight is needed for this route.</div>'}</div><div class="surface-grid">${surface(t.rail)}${surface(t.road)}</div></section><section class="travel-lab"><div class="section-header"><div><span class="eyebrow">MOBILITY AGENT</span><h2>Airport, cab and local movement</h2><p>Useful starting points for transfers; final prices and availability come from the operator.</p></div><span class="tag">${money(p.budget.items.find(x=>x.id==='transport').amount)} ALLOWANCE</span></div><div class="mobility-grid">${(t.cabs||[]).map(c=>`<article class="mobility-card"><div class="transport-icon">${icon('map')}</div><span class="tag">${esc(c.label)}</span><h3>${esc(c.name)}</h3><strong>~${money(c.estimate)}</strong><p>${esc(c.description)}</p>${link(c.url,`Check option ${icon('arrow')}`,'button secondary full')}</article>`).join('')}</div></section><div class="notice"><strong>No booking has been made.</strong> Provider buttons open external websites. Verify the operator, final fare, baggage, cancellation rules and availability before paying.</div>`;
}
async function creditsV2(){await credits();if(!state.preview){const notes=document.querySelectorAll('#credits-content .credit-note'),last=notes[notes.length-1];if(last)last.textContent='Google Maps property data and provider photo credits appear when configured. Budgets are planning estimates; signed-in trips are stored in your VoyageOS account. Booking links open external providers.'}}
async function initV2(){loadSaved();try{const [catalog,config,me]=await Promise.allSettled([fetch('/catalog.json').then(r=>{if(!r.ok)throw Error('Destination catalog is unavailable.');return r.json()}),fetch('/api/config',{signal:AbortSignal.timeout(6000)}).then(r=>{if(!r.ok)throw Error('No API');return r.json()}),fetch('/api/auth/me',{credentials:'same-origin',signal:AbortSignal.timeout(6000)}).then(r=>{if(!r.ok)throw Error('No account API');return r.json()})]);if(catalog.status!=='fulfilled')throw catalog.reason;state.catalog=catalog.value;if(config.status==='fulfilled'&&config.value.service==='voyageos'){state.config=config.value;state.preview=false}if(!state.preview&&me.status==='fulfilled')state.user=me.value.user||null;if(state.user)await loadCloudTrips();else if(!state.preview)state.saved=[];$('#connection').textContent=state.preview?'Interactive preview':state.config?.ai?'7 agents · AI connected':'7 agents · built-in';render()}catch(err){$('#main').innerHTML=`<div class="error-message">${esc(err.message)} Reload the page to try again.</div>`}}
staysView=travelView;
saveTrip=saveTripV2;
savedView=accountSavedView;
init=initV2;
$('#credits-btn').removeEventListener('click',credits);
$('#credits-btn').addEventListener('click',creditsV2);
init();
